mapper.update:
UPDATE user_card_monthly_state
SET current_performance_amount = GREATEST(0, current_performance_amount + #{performanceDelta}),
    shared_limit_used          = GREATEST(0, shared_limit_used + #{sharedLimitDelta})
WHERE user_card_id = #{userCardId}
  AND base_year_month = #{baseYearMonth}

UPDATE user_benefit_usage
SET used_amount = GREATEST(0, used_amount + #{amountDelta}),
    used_count  = GREATEST(0, used_count + #{countDelta})
WHERE user_card_id = #{userCardId}
  AND benefit_id = #{benefitId}
  AND base_year_month = #{baseYearMonth}

mapper.select:
SELECT COALESCE(SUM(s.current_performance_amount), 0)
FROM user_card_monthly_state s
WHERE s.user_card_id = #{userCardId}
  AND s.base_year_month BETWEEN #{fromYearMonth} AND #{toYearMonth}

SELECT sel.user_card_id,
       sel.option_group_code,
       sel.selected_option_key
FROM user_card_benefit_selection sel
WHERE sel.user_card_id = #{userCardId}
  AND sel.base_year_month = #{baseYearMonth}
